import { expect, test } from '@playwright/test'

/**
 * Guards the arrangement in ADR-031: Tailwind's reset below MUI, MUI below
 * Tailwind's utilities.
 *
 * Every assertion here measures the document itself — the layer order the
 * browser resolved, and computed styles — rather than reading the self-check
 * the page renders. That check is a convenience for a person looking at the
 * screen; trusting it here would only assert that the page agrees with itself.
 *
 * The probe classes come from the test, not from the page, and are kept
 * generated by an `@source inline` directive in src/index.css. So this suite
 * survives Phase 5 replacing App.tsx with the real pages.
 */

const PROBE_CLASSES = 'bg-emerald-500 px-10'

/** The order the browser established layer names in, across every stylesheet. */
async function layerOrder(page: import('@playwright/test').Page) {
  return page.evaluate(() => {
    const layers: string[] = []
    for (const sheet of Array.from(document.styleSheets)) {
      let rules: CSSRule[]
      try {
        rules = Array.from(sheet.cssRules)
      } catch {
        continue // cross-origin; none of ours are
      }
      for (const rule of rules) {
        const declaration = /^@layer\s+([^{;]+)/.exec(rule.cssText)
        if (!declaration) {
          continue
        }
        for (const name of declaration[1].split(',').map((part) => part.trim())) {
          if (name && !layers.includes(name)) {
            layers.push(name)
          }
        }
      }
    }
    return layers
  })
}

test.beforeEach(async ({ page }) => {
  await page.goto('/', { waitUntil: 'networkidle' })
  await page.locator('.MuiButton-contained').first().waitFor()
})

test('mui ranks above Tailwind’s reset and below its utilities', async ({ page }) => {
  const layers = await layerOrder(page)

  expect(layers, `layer order was: ${layers.join(' < ')}`).toContain('mui')
  expect(layers.indexOf('mui')).toBeGreaterThan(layers.indexOf('base'))
  expect(layers.indexOf('utilities')).toBeGreaterThan(layers.indexOf('mui'))
})

test('MUI rules are emitted inside @layer mui', async ({ page }) => {
  const blocks = await page.evaluate(() =>
    Array.from(document.styleSheets)
      .flatMap((sheet) => {
        try {
          return Array.from(sheet.cssRules)
        } catch {
          return []
        }
      })
      .filter((rule) => /^@layer\s+mui\s*\{/.test(rule.cssText)).length,
  )

  // Zero means StyledEngineProvider lost its enableCssLayer prop, which leaves
  // MUI's styles unlayered — and unlayered styles beat every layer.
  expect(blocks).toBeGreaterThan(0)
})

test('MUI’s own button styling survives Tailwind’s preflight', async ({ page }) => {
  const button = page.locator('.MuiButton-contained').first()

  // Preflight resets `button` to a transparent box with no padding. If `mui`
  // ranks below Tailwind's `base` layer, that reset wins and this is what is
  // left. Every other check in this file still passes in that state, which is
  // why this one is here.
  await expect(button).not.toHaveCSS('background-color', 'rgba(0, 0, 0, 0)')
  await expect(button).not.toHaveCSS('padding-left', '0px')
})

test('a Tailwind utility overrides the MUI style it collides with', async ({ page }) => {
  const measurements = await page.evaluate((probeClasses) => {
    const original = document.querySelector('.MuiButton-contained')
    if (!original) {
      throw new Error('no contained MUI button on the page to clone')
    }

    // Cloning keeps every MUI class, so the only difference is the utilities
    // the test adds. No !important, no inline styles: if the utilities win,
    // they won on layer order alone.
    const probe = original.cloneNode(true) as HTMLElement
    probe.className = `${original.className} ${probeClasses}`
    document.body.append(probe)

    const before = getComputedStyle(original)
    const after = getComputedStyle(probe)
    const result = {
      muiBackground: before.backgroundColor,
      muiPaddingLeft: before.paddingLeft,
      probeBackground: after.backgroundColor,
      probePaddingLeft: after.paddingLeft,
    }

    probe.remove()
    return result
  }, PROBE_CLASSES)

  expect(
    measurements.probeBackground,
    `MUI ${measurements.muiBackground} vs probe ${measurements.probeBackground}`,
  ).not.toBe(measurements.muiBackground)

  expect(measurements.probePaddingLeft).toBe('40px')
  expect(measurements.probePaddingLeft).not.toBe(measurements.muiPaddingLeft)
})

test('the page loads without console errors', async ({ page }) => {
  const errors: string[] = []
  page.on('console', (message) => {
    if (message.type() === 'error') {
      errors.push(message.text())
    }
  })
  page.on('pageerror', (error) => errors.push(String(error)))

  await page.reload({ waitUntil: 'networkidle' })
  expect(errors).toEqual([])
})
